from __future__ import annotations

from api.operator_console_decision_refresh import CONSOLE_HTML_V41

SUCCESSOR_SCRIPT = r"""
<style>
.successor-panel{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.successor-note{padding:12px;border:1px solid #cfe7d8;background:#f2fbf5;border-radius:10px;color:#147a46;margin-bottom:10px}.successor-warn{padding:12px;border:1px solid #f2dfb8;background:#fff8ea;border-radius:10px;color:#7c4b00;margin-bottom:10px}.successor-confirm{display:flex;gap:9px;align-items:flex-start;padding:12px;border:1px solid #e2edf8;background:#fbfdff;border-radius:10px}.successor-panel button{width:100%;margin-top:10px;border:0;border-radius:10px;padding:12px;background:#1769e0;color:#fff;font-weight:900;cursor:pointer}.successor-panel button:disabled{opacity:.5;cursor:not-allowed}.successor-status{min-height:20px;margin-top:10px;font-size:13px}.successor-status.ok{color:#147a46}.successor-status.err{color:#b42318}
</style>
<script>
async function loadSuccessorReviewControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('successor-review-control');if(!box){box=document.createElement('section');box.id='successor-review-control';box.className='successor-panel';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Create Successor Review Cycle</h3><div class="muted">Checking latest decision refresh…</div>';try{const r=await fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/successor-review-context',{credentials:'same-origin'});if(r.status===401){location.href='/operator/login';return}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.detail||'successor context unavailable')}const d=await r.json();if(!d.ready){box.innerHTML=`<h3>Create Successor Review Cycle</h3><div class="muted">Not available: ${esc((d.reason||'not ready').replaceAll('_',' '))}</div>`;return}const f=d.refresh;box.innerHTML=`<h3>Create Successor Review Cycle</h3><div class="successor-note">Decision refresh ${esc(f.refresh_id)} is ready to become the next review generation.</div><div class="successor-warn"><strong>No authority carries forward.</strong> The new generation starts at prepared_not_approved. The parent cycle becomes historical and its events/actions can no longer advance.</div><label class="successor-confirm"><input type="checkbox" id="successor-confirm"><span>I want to create a new review generation from this refreshed evidence context with no inherited approval, execution, or dispatch authority.</span></label><button id="successor-button">Create successor review generation</button><div id="successor-status" class="successor-status"></div>`;box.querySelector('#successor-button').onclick=async()=>{const status=box.querySelector('#successor-status');const btn=box.querySelector('#successor-button');status.textContent='';status.className='successor-status';if(!box.querySelector('#successor-confirm').checked){status.textContent='Explicit successor-cycle confirmation is required.';status.className='successor-status err';return}btn.disabled=true;try{const csrf=await loadConsoleCsrf();const rr=await fetch('/operator/api/decision-refreshes/'+encodeURIComponent(f.refresh_id)+'/successor-review',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify({confirm_successor_review:true})});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Successor review rejected')}const x=await rr.json();status.textContent=`Generation ${x.successor.generation} created at ${x.successor.record_id}. Prior authority inherited: false.`;status.className='successor-status ok';setTimeout(()=>loadCase(x.successor.record_id),400)}catch(err){status.textContent=String(err.message||err);status.className='successor-status err'}finally{btn.disabled=false}}}catch(err){box.innerHTML=`<h3>Create Successor Review Cycle</h3><div class="muted">${esc(err.message||'Unavailable.')}</div>`}}
const _v41LoadCase=loadCase;loadCase=async function(id){await _v41LoadCase(id);await loadSuccessorReviewControl(id)};setTimeout(()=>{if(selected)loadSuccessorReviewControl(selected)},2100);
</script>
"""

CONSOLE_HTML_V42 = CONSOLE_HTML_V41.replace("</body>", SUCCESSOR_SCRIPT + "</body>")
